  assert.equal(fitForCheck(1_000_000, "Startup", rounds).verdict, "fits");
  assert.equal(fitForCheck(20_000_000, "Startup", rounds).verdict, "too_small");
  assert.equal(fitForCheck(100_000, "Startup", rounds).verdict, "too_large");
