1	"use client";
2	
3	// Founder report (C5, C6): company header, competitor chips, then the Pitch and
4	// Skip lists. Removing competitors and pressing "Re-rank" calls
5	// /api/founder/analyze again with the remaining `competitor_ids`.
6	
7	import Link from "next/link";
8	import { useCallback, useEffect, useRef, useState } from "react";
9	
10	import { ChatPanel } from "@/components/ChatPanel";
11	import { CompetitorChips } from "@/components/CompetitorChips";
12	import { PitchCard, SkipCard } from "@/components/InvestorCard";
13	import { SlowNotice } from "@/components/SlowNotice";
14	import { SourceBadges } from "@/components/SourceBadge";
15	import { analyzeFounder } from "@/lib/api";
16	import { describeError } from "@/lib/errors";
17	import { keptCompetitorIds, prettyEnum } from "@/lib/format";
18	import { prepPath } from "@/lib/routes";
19	import type { Company, FounderReport } from "@/lib/types";
20	
21	// Live reports rank 30-45 investors; the top ones matter, and the Skip list below
22	// (the conflict) must stay within reach: each card is ~235 px tall.
23	const PITCH_SHOWN = 5;
24	
25	type Load =
26	  | { status: "loading" }
27	  | { status: "error"; message: string; notFound: boolean; detail: string | null }
28	  | { status: "ready"; report: FounderReport; reranking: boolean; rerankError: string | null };
29	
30	export function FounderReportView({ companyId }: { companyId: string }) {
31	  const [load, setLoad] = useState<Load>({ status: "loading" });
32	  const [removed, setRemoved] = useState<Set<string>>(new Set());
33	  const [narrowed, setNarrowed] = useState(false); // ranked against a user-edited list
34	  const [showAllPitch, setShowAllPitch] = useState(false);
35	  const abort = useRef<AbortController | null>(null);
36	
37	  // Fetches and stores a report. State is set only in the promise callbacks, so the initial
38	  // load can run from an effect; `run` below flips the loading state first, from handlers.
39	  const fetchReport = useCallback(
40	    (competitorIds?: string[]) => {
41	      abort.current?.abort();
42	      const ctrl = new AbortController();
43	      abort.current = ctrl;
44	      return analyzeFounder(
45	        { company_id: companyId, ...(competitorIds ? { competitor_ids: competitorIds } : {}) },
46	        ctrl.signal,
47	      ).then(
